class Solution {
  public int[] assignEdgeWeights(int[][] edges, int[][] queries) {
    final long MOD = 1_000_000_007L;
    int n = edges.length + 1;
    int[] start = new int[n + 2];
    for (int[] e : edges) {
      start[e[0] + 1]++;
      start[e[1] + 1]++;
    }
    for (int i = 1; i <= n + 1; i++) start[i] += start[i - 1];
    int[] fill = new int[n + 1], to = new int[2 * (n - 1)];
    for (int[] e : edges) {
      to[start[e[0]] + fill[e[0]]++] = e[1];
      to[start[e[1]] + fill[e[1]]++] = e[0];
    }
    int LOG = 1;
    while ((1 << LOG) < n) LOG++;
    int[][] up = new int[LOG + 1][n + 1];
    int[] depth = new int[n + 1], queue = new int[n];
    boolean[] seen = new boolean[n + 1];
    int head = 0, tail = 0;
    queue[tail++] = 1;
    seen[1] = true;
    up[0][1] = 1;
    while (head < tail) {
      int u = queue[head++];
      for (int p = start[u]; p < start[u + 1]; p++) {
        int v = to[p];
        if (seen[v]) continue;
        seen[v] = true;
        up[0][v] = u;
        depth[v] = depth[u] + 1;
        queue[tail++] = v;
      }
    }
    for (int l = 1; l <= LOG; l++) for (int i = 1; i <= n; i++) up[l][i] = up[l - 1][up[l - 1][i]];
    long[] pow2 = new long[n + 1];
    pow2[0] = 1;
    for (int i = 1; i <= n; i++) pow2[i] = pow2[i - 1] * 2 % MOD;
    int[] ans = new int[queries.length];
    for (int qi = 0; qi < queries.length; qi++) {
      int u = queries[qi][0], v = queries[qi][1];
      int a = u, b = v;
      if (depth[a] < depth[b]) {
        int t = a;
        a = b;
        b = t;
      }
      int diff = depth[a] - depth[b];
      for (int l = 0; l <= LOG; l++) if ((diff >> l & 1) != 0) a = up[l][a];
      if (a != b) {
        for (int l = LOG; l >= 0; l--) {
          if (up[l][a] != up[l][b]) {
            a = up[l][a];
            b = up[l][b];
          }
        }
        a = up[0][a];
      }
      int len = depth[u] + depth[v] - 2 * depth[a];
      ans[qi] = len == 0 ? 0 : (int) pow2[len - 1];
    }
    return ans;
  }
}
